package com.dy.artisan3d.data.repositoryimport com.dy.artisan3d.data.mapper.toDomainimport com.dy.artisan3d.data.model.artisan.article.ArtisanArticleResponseimport com.dy.artisan3d.domain.model.artisan.ArtisanArticleimport com.dy.artisan3d.domain.repository.ArtisanArticleRepositoryimport com.dy.artisan3d.util.Constants.BASE_URLimport io.ktor.client.HttpClientimport io.ktor.client.call.bodyimport io.ktor.client.request.getimport io.ktor.client.request.parameterclass ArtisanArticleRepositoryImpl(private val httpClient: HttpClient) : ArtisanArticleRepository {    override suspend fun getArticles(page: Int, lang: String): List<ArtisanArticle> {        return try {            val response: ArtisanArticleResponse = httpClient.get(BASE_URL + "articles") {                parameter("page", page)            }.body()            response.data.map { it.toDomain(lang) }        } catch (e: Exception) {            emptyList<ArtisanArticle>()        }    }}